final _officialPatterns = <_L10nPattern>[
  _L10nPattern(RegExp("^当前会话已使用 ([\\s\\S]*?) tokens，已超过目标模型 ([\\s\\S]*?) 预留最大输出后的可用上下文 ([\\s\\S]*?) tokens。\n请先使用当前模型压缩上下文。压缩完成且上下文用量小于目标模型可用上下文后，会继续切换模型。\$"), "This conversation has used {used} tokens, which exceeds {modelName}'s available context of {target} tokens after reserving maximum output.\nCompress the current conversation with the current model first. If the compressed context fits, ZCode will continue switching models.", {"used": 1, "modelName": 2, "target": 3}),
  _L10nPattern(RegExp("^已导入 ([\\s\\S]*?) 个 Cookie，以及 ([\\s\\S]*?) 个站点的 ([\\s\\S]*?) 条 LocalStorage 数据；另有 ([\\s\\S]*?) 个 Cookie 受 Chrome 系统保护，未导入。\$"), "Imported {cookies} cookies and {entries} LocalStorage entries from {origins} sites; {skipped} cookies were protected by Chrome and were not imported.", {"cookies": 1, "origins": 2, "entries": 3, "skipped": 4}),
  _L10nPattern(RegExp("^已导入 ([\\s\\S]*?) 个 Cookie，以及 ([\\s\\S]*?) 个站点的 ([\\s\\S]*?) 条 LocalStorage 数据；另有 ([\\s\\S]*?) 个 Cookie 未导入。\$"), "Imported {cookies} cookies and {entries} LocalStorage entries from {origins} sites; {skipped} cookies were not imported.", {"cookies": 1, "origins": 2, "entries": 3, "skipped": 4}),
  _L10nPattern(RegExp("^第 ([\\s\\S]*?) 轮的 ([\\s\\S]*?)（([\\s\\S]*?)）暂不支持分享，将被跳过。当前支持：([\\s\\S]*?)。\$"), "Turn {turnOrdinal}: {artifactDisplayName} ({artifactType}) cannot be shared and will be skipped. Supported types: {allowedFormats}.", {"turnOrdinal": 1, "artifactDisplayName": 2, "artifactType": 3, "allowedFormats": 4}),
  _L10nPattern(RegExp("^第 ([\\s\\S]*?) 轮的 ([\\s\\S]*?)（([\\s\\S]*?)）暂不支持分享，已跳过。当前支持：([\\s\\S]*?)。\$"), "Turn {turnOrdinal}: {artifactDisplayName} ({artifactType}) is not supported and was skipped. Supported types: {allowedFormats}.", {"turnOrdinal": 1, "artifactDisplayName": 2, "artifactType": 3, "allowedFormats": 4}),
  _L10nPattern(RegExp("^打开运行中的后台任务：Bash ([\\s\\S]*?) 个，工作流 ([\\s\\S]*?) 个，子智能体 ([\\s\\S]*?) 个，共 ([\\s\\S]*?) 个\$"), "Open running background tasks: {bashCount} Bash, {workflowCount} workflow, {subagentCount} Subagent, {count} total", {"bashCount": 1, "workflowCount": 2, "subagentCount": 3, "count": 4}),
  _L10nPattern(RegExp("^同步失败：所选 Skills 的内容总大小约为 ([\\s\\S]*?)，超过单次同步上限 ([\\s\\S]*?)。请取消选择部分 Skills 后重试；远端未写入任何内容。\$"), "Sync failed: the selected Skills contain about {actualSize} of content, exceeding the {maxSize} per-sync limit. Deselect some Skills and try again. Nothing was written to the remote host.", {"actualSize": 1, "maxSize": 2}),
  _L10nPattern(RegExp("^已导入 ([\\s\\S]*?) 个站点的 ([\\s\\S]*?) 条 LocalStorage 数据，但 Windows App-Bound Cookie 未导入。\$"), "Imported {entries} LocalStorage entries from {origins} sites, but Windows App-Bound cookies were not imported.", {"origins": 1, "entries": 2}),
  _L10nPattern(RegExp("^当前版本 v([\\s\\S]*?) 低于最低可用版本 v([\\s\\S]*?)。请先完成升级，升级前暂时无法继续使用当前客户端。\$"), "Your current version v{currentVersion} is below the minimum supported version v{minimalVersion}. Update first before continuing with this client.", {"currentVersion": 1, "minimalVersion": 2}),
  _L10nPattern(RegExp("^第 ([\\s\\S]*?) 轮的 ([\\s\\S]*?) 无法读取，已跳过。如果确实需要分享该文件，请重新生成后再分享。\$"), "Turn {turnOrdinal}: {artifactDisplayName} could not be read, so it was skipped. If it should have been shared, regenerate the file and share again.", {"turnOrdinal": 1, "artifactDisplayName": 2}),
  _L10nPattern(RegExp("^请求体至少带上当前 botId、稳定的 userId、`chatType: \"private\"`，并把 text 设成 ([\\s\\S]*?)。\$"), "The payload should at least include this botId, a stable userId, `chatType: \"private\"`, and set text to {command}.", {"command": 1}),
  _L10nPattern(RegExp("^已导入 ([\\s\\S]*?) 个 Cookie，以及 ([\\s\\S]*?) 个站点的 ([\\s\\S]*?) 条 LocalStorage 数据。\$"), "Imported {cookies} cookies and {entries} LocalStorage entries from {origins} sites.", {"cookies": 1, "origins": 2, "entries": 3}),
  _L10nPattern(RegExp("^Claude Code 未知命令 ([\\s\\S]*?)（参数：([\\s\\S]*?)）。请确认命令名称，或切换到支持该命令的 Agent/技能后重试。\$"), "Claude Code does not recognize {command} (args: {args}). Check the command name, or switch to an Agent/skill that supports it and try again.", {"command": 1, "args": 2}),
  _L10nPattern(RegExp("^([\\s\\S]*?) 需要更新 ZCode\nDesktop ([\\s\\S]*?) → ([\\s\\S]*?)，请更新 ZCode 后重新连接。\$"), "ZCode has an update for {source}\nDesktop {current} → {available}; update ZCode to match this Source.", {"source": 1, "current": 2, "available": 3}),
  _L10nPattern(RegExp("^([\\s\\S]*?) 大小为 ([\\s\\S]*?)，超过单文件上限 ([\\s\\S]*?)，请取消该轮或重新生成较小文件。\$"), "{artifactDisplayName} is {actual}, above the per-file limit of {limit}. Deselect the turn or regenerate a smaller file.", {"artifactDisplayName": 1, "actual": 2, "limit": 3}),
  _L10nPattern(RegExp("^已导入 ([\\s\\S]*?) 个 Cookie，但部分 LocalStorage 数据未导入。关闭 Chrome 后重试可提高成功率。\$"), "Imported {cookies} cookies, but some LocalStorage data was not imported. Closing Chrome before retrying may improve the result.", {"cookies": 1}),
  _L10nPattern(RegExp("^ZCode 电脑控制仍在准备中——工具尚未加载（已加载 ([\\s\\S]*?) 个）。请先授予下方权限，Helper 就绪后工具会自动出现。\$"), "ZCode Computer Use is still preparing — its tools aren't loaded yet ({count} loaded). Grant the permissions below; tools appear once the helper is ready.", {"count": 1}),
  _L10nPattern(RegExp("^我用 ZCode 高速卡节省了 ([\\s\\S]*?) 秒的时间，你也来试试吧。下载 ZCode https://zcode\\.z\\.ai\$"), "I used the ZCode Highspeed card and saved {duration}s. Give it a try. Download ZCode https://zcode.z.ai", {"duration": 1}),
  _L10nPattern(RegExp("^同步失败：生成的同步包约为 ([\\s\\S]*?)，超过单次同步上限 ([\\s\\S]*?)。请减少选择后重试；远端未写入任何内容。\$"), "Sync failed: the generated sync archive is about {actualSize}, exceeding the {maxSize} per-sync limit. Deselect some Skills and try again. Nothing was written to the remote host.", {"actualSize": 1, "maxSize": 2}),
